      const usage=p.processed?(p.usedQuantity>0?`后续料理要用 ${fmt(p.usedQuantity)} 份${p.directQuantity>0?` · 另有 ${fmt(p.directQuantity)} 份直接卖`:''}`:'本次加工后全部直接卖'):'';
