  function syncColumns(){columnObserver?.disconnect();const layout=document.querySelector('.layout'),left=layout?.querySelector('.card');if(!left)return;const sync=()=>layout.style.setProperty('--input-height',Math.max(560,Math.ceil(left.getBoundingClientRect().height))+'px');sync();columnObserver=new ResizeObserver(sync);columnObserver.observe(left);}
