  document.querySelector('#page').addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)go(b.dataset.go);const check=e.target.closest('[data-complete]');if(check){const id=Number(check.dataset.complete),session=state.sessions[tab],p=session?.result.plan.find(p=>p.id===id);if(p)updateDone(id,session.done[id]===p.quantity?0:p.quantity);}const add=e.target.closest('[data-done-add]');if(add){const id=Number(add.dataset.doneAdd),session=state.sessions[tab],p=session?.result.plan.find(p=>p.id===id);if(p&&!add.disabled&&Progress.canAddBatch(p,session.done[id]||0))updateDone(id,(session.done[id]||0)+Progress.batchSize(p));}const resume=e.target.closest('[data-resume]');if(resume)resumePlan(resume.dataset.resume);});
